def weighted_score(profile, priorities):
    mapping = {
        "Financial Gain / Upside": "financial",
        "Happiness & Fulfillment": "happiness",
        "Work-Life Balance": "balance",
        "Long-Term Personal Growth": "growth",
        "Risk Tolerance": "risk",
    }
    total = sum(priorities.values()) or 1
    score = 0
    for label, weight in priorities.items():
        key = mapping[label]
        value = profile[key]
        # Risk tolerance is a preference for uncertainty, so high tolerance
        # rewards a higher-risk path rather than treating risk itself as bad.
        if key == "risk":
            value = 100 - abs(profile["risk"] - (weight * 10))
        score += value * weight
    return score / total

# ---------- AI Layer: Local Ollama + Llama 3.2 REST Integration ----------
OLLAMA_BASE_URL = "http://127.0.0.1:11434"
DEFAULT_MODEL = "llama3.2"

def get_ollama_model():
    """Return the local model name, defaulting to llama3.2. No API key is required."""
    try:
        model = st.secrets.get("OLLAMA_MODEL", os.getenv("OLLAMA_MODEL", DEFAULT_MODEL))
    except Exception:
        model = os.getenv("OLLAMA_MODEL", DEFAULT_MODEL)
    return (model or DEFAULT_MODEL).strip()

@st.cache_data(ttl=5)
def check_ollama_health():
    """Verify that the local Ollama server is reachable and llama3.2 is available.
    Returns: (is_ready: bool, message: str, error_type: str)
    """
    target_model = get_ollama_model()
    clean_target = target_model.split(":")[0].lower()
    url = f"{OLLAMA_BASE_URL}/api/tags"

    try:
        if requests is not None:
            resp = requests.get(url, timeout=3.0)
            if resp.status_code != 200:
                return False, f"Cannot connect to Ollama at {OLLAMA_BASE_URL} (HTTP {resp.status_code}).", "http_error"
            data = resp.json()
        else:
            req = urllib.request.Request(url)
            with urllib.request.urlopen(req, timeout=3.0) as resp:
                data = json.loads(resp.read().decode("utf-8"))

        models = [m.get("name", "").lower() for m in data.get("models", [])]
        found = any(m == target_model.lower() or m.startswith(f"{clean_target}:") or m == clean_target for m in models)
        if found:
            return True, f"Ollama: Connected | Model: {target_model}", ""
        else:
            return False, f"The {target_model} model was not found. Run: ollama pull {target_model}", "model_not_found"

    except Exception as e:
        err_str = str(e).lower()
        if "timeout" in err_str:
            return False, f"Cannot connect to Ollama at {OLLAMA_BASE_URL} (Request timed out).", "timeout"
        return False, f"Cannot connect to Ollama at {OLLAMA_BASE_URL}.", "connection_error"

def ai_ready():
    """Return True if local Ollama server is reachable and target model is ready."""
    ready, _, _ = check_ollama_health()
    return ready

def query_ollama_chat(messages, temperature=0.2, num_predict=800, timeout=45):
    """Query the local Ollama REST API directly via POST http://127.0.0.1:11434/api/chat.
    Robustly handles timeouts, connection failures, HTTP errors, and response extraction.
    """
    target_model = get_ollama_model()
    payload = {
        "model": target_model,
        "messages": messages,
        "stream": False,
        "options": {
            "temperature": temperature,
            "num_predict": num_predict,
        }
    }
    url = f"{OLLAMA_BASE_URL}/api/chat"

    try:
        if requests is not None:
            resp = requests.post(url, json=payload, timeout=timeout)
            status_code = resp.status_code
            resp_text = resp.text
            try:
                data = resp.json()
            except Exception:
                data = None
        else:
            req = urllib.request.Request(
                url,
                data=json.dumps(payload).encode("utf-8"),
                headers={"Content-Type": "application/json"}
            )
            with urllib.request.urlopen(req, timeout=timeout) as resp:
                status_code = resp.status
                resp_text = resp.read().decode("utf-8")
                try:
                    data = json.loads(resp_text)
                except Exception:
                    data = None

    except Exception as e:
        err_str = str(e).lower()
        if "timeout" in err_str:
            raise RuntimeError(f"Ollama request timed out after {timeout} seconds at {OLLAMA_BASE_URL}.")
        if "connection" in err_str or "refused" in err_str or "operation not permitted" in err_str or "errno 61" in err_str:
            raise RuntimeError(f"Cannot connect to Ollama at {OLLAMA_BASE_URL}.")
        raise RuntimeError(f"Cannot connect to Ollama at {OLLAMA_BASE_URL}: {e}")

    if status_code == 404:
        raise RuntimeError(f"The {target_model} model was not found. Run: ollama pull {target_model}")
    elif status_code != 200:
        err_msg = ""
        if data and isinstance(data, dict) and "error" in data:
            err_msg = data["error"]
        raise RuntimeError(f"Ollama returned HTTP error {status_code}: {err_msg or resp_text}")

    if not data or not isinstance(data, dict):
        raise RuntimeError("Ollama returned malformed or unparseable JSON.")

    content = data.get("message", {}).get("content", "")
    if not content or not content.strip():
        raise RuntimeError("Llama returned an empty response. Try restarting Ollama with: ollama serve")

    return content.strip()

class OllamaRestClient:
    """Lightweight compatibility client using the local Ollama REST API."""
    def __init__(self, host=OLLAMA_BASE_URL):
        self.host = host

    def chat(self, model=None, messages=None, options=None, timeout=60, **kwargs):
        options = options or {}
        temperature = options.get("temperature", 0.2)
        num_predict = options.get("num_predict", 800)
        content = query_ollama_chat(messages, temperature=temperature, num_predict=num_predict, timeout=timeout)
        
        class _Message:
            def __init__(self, text):
                self.content = text
        class _Response:
            def __init__(self, text):
                self.message = _Message(text)
        return _Response(content)

def get_ollama_client():
    return OllamaRestClient()

def extract_and_parse_json(text):
    """Safely parse JSON from model output, removing markdown code fences and handling whitespace."""
    if not text:
        return None
    cleaned = text.strip()

    # Strip markdown code blocks ```json ... ``` or ``` ... ```
    if cleaned.startswith("```"):
        lines = cleaned.splitlines()
        if lines and lines[0].startswith("```"):
            lines = lines[1:]
        if lines and lines[-1].strip() == "```":
            lines = lines[:-1]
        cleaned = "\n".join(lines).strip()

    try:
        return json.loads(cleaned)
    except Exception:
        pass

    # Extract JSON between outermost curly braces
    first_brace = cleaned.find("{")
    last_brace = cleaned.rfind("}")
    if first_brace != -1 and last_brace != -1 and last_brace > first_brace:
        candidate = cleaned[first_brace:last_brace + 1]
        try:
            return json.loads(candidate)
        except Exception:
            pass

    # Attempt to close open JSON object if slightly truncated
    if first_brace != -1:
        for suffix in ["}", "]}", "\"]}", "\"]}}"]:
            try:
                return json.loads(cleaned[first_brace:] + suffix)
            except Exception:
                pass

    return None

def fallback_decision_data(raw_text=""):
    """Produce structured fallback data from available text so the UI never breaks."""
    options_data = []
    for opt in st.session_state.options:
        options_data.append({
            "title": opt["title"],
            "financial": 70,
            "happiness": 70,
            "balance": 65,
            "growth": 75,
            "risk": 55,
            "benefits": ["Aligned with core stated goals", "Offers actionable upside", "Provides structured progression"],
            "risks": ["Resource commitment required", "Opportunity cost of alternative choices", "Execution uncertainty"],
            "analysis": f"Simulated analysis based on weighted priorities for {opt['title']}.",
        })
    advice = clean_ai_output(raw_text) if raw_text else "Weigh your personal values and immediate trade-offs carefully before committing."
    if len(advice) > 300:
        advice = advice[:300] + "..."
    return {
        "options": options_data,
        "overall_advice": advice,
    }

def clean_ai_output(text):
    if not text:
        return ""
    lines = []
    for line in text.splitlines():
        lower = line.lower()
        if "http://" in lower or "https://" in lower or "www." in lower:
            continue
        lines.append(line.rstrip())
    return "\n".join(lines).strip()
def decision_context():
    options = "\n".join(f"- {o['title']}: {o['desc']}" for o in st.session_state.options)
    priorities = "\n".join(f"- {k}: {v}/10" for k, v in st.session_state.priorities.items())
    answers = (
        f"Biggest fear: {st.session_state.q1 or 'Not provided'}\n"
        f"Reversibility in 12 months: {st.session_state.q2 or 'Not provided'}\n"
        f"Definition of success: {st.session_state.q3 or 'Not provided'}"
    )
    return f"""
DILEMMA:
{st.session_state.dilemma or 'Not provided'}

CONTEXT:
{st.session_state.context or 'Not provided'}

OPTIONS:
{options}

PRIORITIES:
{priorities}

CLARIFYING ANSWERS:
{answers}
"""

def build_recommendation_text(results, overall_advice=""):
    if not results:
        return ""
    best = results[0]
    confidence = "High" if best["score"] >= 75 else "Medium" if best["score"] >= 60 else "Low"
    why = best.get("analysis", "") or "This option has the strongest alignment with your stated priorities."
    advice = overall_advice or "Use this recommendation as a structured decision aid, not a guarantee."
    return (
        "Recommendation: " + best["title"] + "\n\n" +
        "Why: " + why + "\n\n" +
        "Confidence: " + confidence + "\n\n" +
        "Key factor: Your highest-weight priorities and the trade-off between upside, fulfilment, balance and risk.\n\n" +
        "Overall advice: " + advice
    )

def get_ai_analysis():
    """Ask local Llama to analyze every option and return structured JSON."""
    ready, err_msg, _ = check_ollama_health()
    if not ready:
        raise RuntimeError(err_msg)

    options_text = ""
    schema_items = []
    for i, option in enumerate(st.session_state.options):
        options_text += f"\nOPTION {i + 1}:\nTitle: {option['title']}\nDescription: {option['desc']}\n"
        schema_items.append(f"""    {{
      "title": "{option['title']}",
      "financial": 70,
      "happiness": 75,
      "balance": 60,
      "growth": 85,
      "risk": 60,
      "benefits": ["Benefit 1", "Benefit 2", "Benefit 3"],
      "risks": ["Risk 1", "Risk 2", "Risk 3"],
      "analysis": "2-3 sentences evaluating this option."
    }}""")

    schema_example = ",\n".join(schema_items)
    priorities_text = "\n".join(
        f"- {key}: {value}/10"
        for key, value in st.session_state.priorities.items()
    )

    prompt = f"""You are an intelligent decision-support system called The Butterfly Effect.

Your job is NOT to predict the future. Analyze this user's actual decision, context,
priorities and clarifying answers. Compare every option fairly and identify trade-offs.

USER'S DILEMMA:
{st.session_state.dilemma or "Not specified"}

BACKGROUND CONTEXT:
{st.session_state.context or 'Not provided'}

OPTIONS:
{options_text}

USER PRIORITIES:
{priorities_text}

ADDITIONAL REFLECTIONS:
Biggest fear: {st.session_state.q1 or 'Not provided'}
How reversible is the decision: {st.session_state.q2 or 'Not provided'}
Definition of success: {st.session_state.q3 or 'Not provided'}

For EVERY option, assign scores from 0 to 100 for: financial, happiness, balance, growth, risk.
Provide exactly 3 specific benefits, exactly 3 specific risks, and a concise analysis for EACH option.
Then provide balanced overall advice.

IMPORTANT: Return ONLY a valid JSON object matching this schema. No markdown code blocks, no other text.
{{
  "options": [
{schema_example}
  ],
  "overall_advice": "Balanced overall advice."
}}"""

    content = query_ollama_chat([{"role": "user", "content": prompt}], temperature=0.2, num_predict=1500, timeout=60)
    parsed = extract_and_parse_json(content)
    if parsed and isinstance(parsed, dict) and "options" in parsed:
        return parsed

    # Retry once if parsing fails (Requirement 17)
    repair_prompt = f"""Return ONLY a valid JSON object matching this schema. Fix any format or syntax issues:
{content}

Required schema:
{{
  "options": [
{schema_example}
  ],
  "overall_advice": "Balanced overall advice."
}}"""
    try:
        repaired_content = query_ollama_chat([{"role": "user", "content": repair_prompt}], temperature=0.1, num_predict=1500, timeout=45)
        repaired = extract_and_parse_json(repaired_content)
        if repaired and isinstance(repaired, dict) and "options" in repaired:
            return repaired
    except Exception:
        pass

    return fallback_decision_data(content)

def generate_quick_recommendation(question):
    """Generate quick direct advice from Llama 3.2 without using JSON mode."""
    ready, err_msg, _ = check_ollama_health()
    if not ready:
        raise RuntimeError(err_msg)

    prompt = f"""You are The Butterfly Effect, a concise local decision-support AI.
Analyze this uncertain choice using the user's wording. Choose ONE best-fit option; do not say only 'it depends'.
Give a practical recommendation in 2-4 short sentences. Do not mention prompts, models or sources.

CHOICE:
{question}

Return exactly:
RECOMMENDATION: <clear recommended choice>
WHY: <2-4 concise sentences>
CONFIDENCE: <High / Medium / Low>
KEY FACTOR: <one key decisive factor>
"""
    content = query_ollama_chat([{"role": "user", "content": prompt}], temperature=0.2, num_predict=500, timeout=35)
    return clean_ai_output(content)

def generate_recommendation():
    if not st.session_state.simulation:
        return ""
    return build_recommendation_text(st.session_state.simulation, st.session_state.get("overall_advice", ""))

def generate_decision_analysis():
    data = get_ai_analysis()
    temp = []
    ai_options = data.get("options", [])
    for i, option in enumerate(st.session_state.options):
        ai = ai_options[i] if i < len(ai_options) else {}
        profile = {k: int(max(0, min(100, ai.get(k, 50)))) for k in ["financial", "happiness", "balance", "growth", "risk"]}
        temp.append({
            "title": option["title"],
            "desc": option["desc"],
            "profile": profile,
            "score": weighted_score(profile, st.session_state.priorities),
            "analysis": ai.get("analysis", ""),
            "benefits": ai.get("benefits", [])[:3] or ["Key strategic alignment", "Growth opportunity", "Clear pathway"],
            "risks": ai.get("risks", [])[:3] or ["Execution challenges", "Opportunity cost", "Resource commitment"],
        })
    temp.sort(key=lambda x: x["score"], reverse=True)
    best_score = temp[0]["score"] if temp else 0
    for t in temp:
        t["regret"] = best_score - t["score"]
    st.session_state.simulation = temp
    st.session_state.overall_advice = data.get("overall_advice", "")
    return build_recommendation_text(temp, data.get("overall_advice", ""))

def generate_scenario(option_title, horizon):
    ready, err_msg, _ = check_ollama_health()
    if not ready:
        raise RuntimeError(err_msg)

    prompt = f"""Explore a plausible {horizon}-year scenario if the user chooses: {option_title}.
Do not predict the future with certainty. Use only the user's information and general reasoning.
Mention likely opportunities, trade-offs, risks and what the user could control. Keep it under 180 words.

{decision_context()}
"""
    content = query_ollama_chat([{"role": "user", "content": prompt}], temperature=0.4, num_predict=500, timeout=35)
    return clean_ai_output(content)

def generate_regret_reflection(horizon):
    ready, err_msg, _ = check_ollama_health()
    if not ready:
        raise RuntimeError(err_msg)

    prompt = f"""Looking back {horizon} years, compare the likely regret of each option in this decision.
Focus on opportunity cost, reversibility, personal priorities and what the user may value later.
Recommend the option with the stronger fit, but clearly state what could change that recommendation.
Keep it under 180 words.

{decision_context()}
"""
    content = query_ollama_chat([{"role": "user", "content": prompt}], temperature=0.4, num_predict=500, timeout=35)
    return clean_ai_output(content)

def calculate_sensitivity():
    """Test how single-priority adjustments affect the top recommendation."""
    if not st.session_state.simulation or len(st.session_state.simulation) < 2:
        return []
    base_results = st.session_state.simulation
    current_winner = base_results[0]["title"]
    base_priorities = st.session_state.priorities
    rows = []

    for priority_name, original_val in base_priorities.items():
        for test_val in range(1, 11):
            if test_val == original_val:
                continue
            test_priorities = dict(base_priorities)
            test_priorities[priority_name] = test_val
            scores = [(r["title"], weighted_score(r["profile"], test_priorities)) for r in base_results]
            scores.sort(key=lambda x: x[1], reverse=True)
            new_winner = scores[0][0]
            if new_winner != current_winner:
                diff = test_val - original_val
                rows.append({
                    "Priority": priority_name,
                    "Current Value": original_val,
                    "Flips At Value": test_val,
                    "Change Needed": f"{'+' if diff > 0 else ''}{diff}",
                    "New Strongest Option": new_winner,
                })
                break
    return rows

def run_simulation():
    """Use the local Ollama model to score and explain every option."""
    if len(st.session_state.options) < 2:
        raise RuntimeError("Add at least two choices before running the simulation.")
    if not st.session_state.dilemma.strip():
        raise RuntimeError("Please enter your dilemma before running the simulation.")

    ai_data = get_ai_analysis()

    priorities = st.session_state.priorities
    ai_options = ai_data.get("options", [])
    results = []

    # Match AI results to the user's actual options by position first,
    # then by title. This keeps the user's original descriptions intact.
    for i, option in enumerate(st.session_state.options):
        ai_option = ai_options[i] if i < len(ai_options) else {}
        profile = {
            "financial": int(max(0, min(100, ai_option.get("financial", 50)))),
            "happiness": int(max(0, min(100, ai_option.get("happiness", 50)))),
            "balance": int(max(0, min(100, ai_option.get("balance", 50)))),
            "growth": int(max(0, min(100, ai_option.get("growth", 50)))),
            "risk": int(max(0, min(100, ai_option.get("risk", 50)))),
        }
        score = weighted_score(profile, priorities)
        results.append({
            "title": option["title"],
            "desc": option["desc"],
            "profile": profile,
            "score": score,
            "benefits": ai_option.get("benefits", [])[:3] or ["Key strategic alignment", "Growth opportunity", "Clear pathway"],
            "risks": ai_option.get("risks", [])[:3] or ["Execution challenges", "Opportunity cost", "Resource commitment"],
            "analysis": ai_option.get("analysis", "") or f"Simulation reflects weighted trade-offs for {option['title']}.",
        })

    if not results:
        raise RuntimeError("Add at least two choice options before running the simulation.")

    results.sort(key=lambda x: x["score"], reverse=True)
    best_score = results[0]["score"]
    for result in results:
        result["regret"] = best_score - result["score"]

    st.session_state.simulation = results
    st.session_state.overall_advice = ai_data.get("overall_advice", "")
    st.session_state.ai_analysis = build_recommendation_text(results, st.session_state.overall_advice)
    st.session_state.page = "dashboard"
    st.session_state.active_option = 0
    st.session_state.horizon = 3

def scenario_text(result, horizon):
    name = result["title"]
    score = result["score"]
    if horizon == 1:
        return f"In the first year, {name} is modelled at {score:.0f}% priority alignment based on the local AI's assessment of your stated priorities."
    if horizon == 3:
        return f"At the three-year horizon, {name} has a simulated alignment of {score:.0f}%. The AI analysis highlights the trade-offs between its benefits, risks and your priorities."
    return f"At five years, {name} reaches a simulated alignment of {score:.0f}%. Long-term outcomes remain uncertain and depend on changing priorities, choices and external events."

